// Sample nutrition-label texts as an on-device reader would produce them, with the values
// that should be read. US and EU layouts, several languages, and typical OCR slips. Synthetic.
import type { LabelRead } from "@/lib/nutrition/labelParse";
import type { Nutrients } from "@/lib/nutrition/food";

export type LabelSample = { name: string; text: string; layout: LabelRead["layout"]; perServing?: Nutrients; per100g?: Nutrients; servingGrams?: number | null; servings?: number | null; allergens?: string[]; traces?: string[]; unsure?: string[] };

const US = (o: { size: string; per?: string; cal: number; fat: string; sat: string; trans?: string; chol: string; sod: string; carb: string; fib: string; sug: string; added?: string; pro: string; tail?: string }) =>
  `Nutrition Facts\n${o.per ?? "8 servings per container"}\nServing size ${o.size}\nAmount per serving\nCalories ${o.cal}\n% Daily Value*\nTotal Fat ${o.fat} 10%\nSaturated Fat ${o.sat} 5%\nTrans Fat ${o.trans ?? "0g"}\nCholesterol ${o.chol} 0%\nSodium ${o.sod} 7%\nTotal Carbohydrate ${o.carb} 13%\nDietary Fiber ${o.fib} 14%\nTotal Sugars ${o.sug}\n${o.added ? `Includes ${o.added} Added Sugars 20%\n` : ""}Protein ${o.pro}\nVitamin D 2mcg 10%\nCalcium 260mg 20%\nIron 8mg 45%\nPotassium 240mg 6%\n${o.tail ?? ""}`;

